package com.luminor.tavernquest.feature.onboarding.hero
import androidx.lifecycle.*;import com.luminor.tavernquest.domain.model.*;import com.luminor.tavernquest.domain.usecase.onboarding.CreateHeroUseCase;import dagger.hilt.android.lifecycle.HiltViewModel;import javax.inject.Inject;import kotlinx.coroutines.flow.*;import kotlinx.coroutines.launch
@HiltViewModel class HeroCreationViewModel @Inject constructor(private val create:CreateHeroUseCase):ViewModel(){private val _ui=MutableStateFlow(HeroCreationUiState());val ui=_ui.asStateFlow();fun name(v:String){_ui.update{it.copy(name=v,error=null)}};fun clazz(v:HeroClass){_ui.update{it.copy(heroClass=v)}};fun appearance(v:HeroAppearance){_ui.update{it.copy(appearance=v)}};fun save(){val s=_ui.value;if(s.name.isBlank())return;viewModelScope.launch{_ui.update{it.copy(saving=true,error=null)};runCatching{create(s.name,s.heroClass,s.appearance)}.onSuccess{_ui.update{it.copy(saving=false,created=true)}}.onFailure{e->_ui.update{it.copy(saving=false,error=e.message?:"Não foi possível criar o perfil.")}}}}}
